public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int[] left = new int[n];
    int[] right = new int[n];
    int[] areas = new int[n];

    Stack<Integer> stack = new Stack<>();
    stack.push(-1);

    for (int i = 0; i < n; i++) {
        while (stack.peek() != -1 && heights[i] <= heights[stack.peek()]) {
            int top = stack.pop();
            left[top] = i;
        }
        stack.push(i);
    }

    stack.push(n);

    for (int i = n - 1; i >= 0; i--) {
        while (stack.peek() != n && heights[i] <= heights[stack.peek()]) {
            int top = stack.pop();
            right[top] = i;
